{"file":{"path":"src/Character.tsx","folder":"src","module":"src","kind":"module","lineCount":77,"hash":"e7334c3b96e5bb1ccd56e7dd390245b22dbfe8b95e0ec8f9f48b852bb701f917","fanIn":1,"fanOut":1},"imports":[{"path":"src/api.ts","hash":"598f191dc8fd3dc3b5535019cce51158efcac3e11a6233de325e09433099329f","role":"module"}],"importedBy":[{"path":"src/Layout.tsx","hash":"120bc5f2577f5bf787e5e4413719f3d68d31f4735a3d01e6bca712b2179eead4","role":"component"}],"source":"import { Link as RouterLink, useParams } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import {
  characterQueryOptions,
  filmQueryOptions,
  homeworldQueryOptions,
} from './api'

export default function Character() {
  const params = useParams()
  const characterId = params.characterId!

  const { status, data } = useQuery(characterQueryOptions(characterId))

  if (status === 'pending') return <p>Loading...</p>
  if (status === 'error') return <p>Error :(</p>

  const homeworldUrlParts = data.homeworld.split('/').filter(Boolean)
  const homeworldId = homeworldUrlParts[homeworldUrlParts.length - 1]

  return (
    <div>
      <h2 className="text-4xl">{data.name}</h2>
      <p>
        <strong>Born</strong>: {data.birth_year}
      </p>
      <p>
        <strong>Eyes</strong>: {data.eye_color}
      </p>
      <p>
        <strong>Hair</strong>: {data.hair_color}
      </p>
      <p>
        <strong>Height</strong>: {data.height}
      </p>
      <p>
        <strong>Mass</strong>: {data.mass}
      </p>
      <p>
        <strong>Homeworld</strong>: <Homeworld homeworldId={homeworldId} />
      </p>

      <h4 className="text-2xl pt-4">Films</h4>
      {data.films.map((film) => {
        const filmUrlParts = film.split('/').filter(Boolean)
        const filmId = filmUrlParts[filmUrlParts.length - 1]
        return <Film filmId={filmId} key={`${filmId}`} />
      })}
    </div>
  )
}

function Film({ filmId }: { filmId: string }) {
  const { data, status } = useQuery(filmQueryOptions(filmId))

  if (status === 'success') {
    return (
      <RouterLink
        className="text-blue-500 hover:underline"
        to={`/films/${filmId}`}
      >
        <h6 className="text-lg">
          {data.episode_id}. {data.title}
        </h6>
      </RouterLink>
    )
  }
}

function Homeworld({ homeworldId }: { homeworldId: string }) {
  const { data, status } = useQuery(homeworldQueryOptions(homeworldId))

  if (status === 'pending') return <span>Loading...</span>
  if (status === 'error') return <span>Error :(</span>

  return <span>{data.name}</span>
}
"}

