{"file":{"path":"src/SearchResults.tsx","folder":"src","module":"src","kind":"module","lineCount":80,"hash":"eaf31b4f10f5db6984171ab224ce83dac9d9545c0267ffed1035cd932ff7252e","fanIn":1,"fanOut":1},"imports":[{"path":"src/useAlgolia.ts","hash":"19d22fb51fc8f078600741becd75811410cf7b7e65d718eff6222bd8ed8fe333","role":"hook"}],"importedBy":[{"path":"src/Search.tsx","hash":"41d3d1d6855b4241a1fc1912b1528e745e2f7128689b1ce6836840257f3e3a3a","role":"component"}],"source":"import useAlgolia from './useAlgolia'

type Product = {
  name: string
  shortDescription: string
  salePrice: number
}

type SearchResultsProps = {
  query: string
}

export default function SearchResults({ query = '' }: SearchResultsProps) {
  const {
    data: hits,
    error,
    isLoading,
    isFetching,
    status,
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
  } = useAlgolia<Product>({
    indexName: 'bestbuy',
    query,
    hitsPerPage: 5,
    staleTime: 1000 * 30, // 30s
    gcTime: 1000 * 60 * 15, // 15m
  })

  if (!query) return null

  if (isLoading) return <div className="loading">Loading...</div>

  if (status === 'error') return <div>Error: {error.message}</div>

  return (
    <div>
      <div className="search-status">
        Status: {status} {isFetching && <span>fetching...</span>}
      </div>
      <div>
        <div className="search-result">
          {hits && hits.length > 0 ? (
            hits.map((product) => (
              <li key={product.objectID} className="product">
                <span className="product-name">{product.name}</span>
                {product.shortDescription && (
                  <>
                    <br />
                    <span className="product-description">
                      {product.shortDescription}
                    </span>
                  </>
                )}
                <br />
                <span className="product-price">${product.salePrice}</span>
              </li>
            ))
          ) : (
            <h3>No products found!</h3>
          )}
        </div>
        {hasNextPage && (
          <button
            type="button"
            className="search-more"
            onClick={() => fetchNextPage()}
            disabled={isFetching}
          >
            more
          </button>
        )}
        {isFetchingNextPage && (
          <div className="search-status">Fetching next page...</div>
        )}
      </div>
    </div>
  )
}
